import os
import boto3


def get_vision_client(region=None):
    region = region or os.getenv("AWS_DEFAULT_REGION", "us-west-2")
    return boto3.client("rekognition", region_name=region)

def normalize_labels(response):
    return [
        {"name": label["Name"], "confidence": label["Confidence"] / 100.0}
        for label in response["Labels"]
    ]


def normalize_text(response):
    return [detection["DetectedText"] for detection in response["TextDetections"]]


def normalize_safety_score(response):
    return response["ModerationLabels"][0]["Confidence"] / 100.0 if response["ModerationLabels"] else 1.0

from [HELPER] vision_client import get_vision_client
from [HELPER] vision_models import normalize_labels, normalize_text, normalize_safety_score


def summarize_visual_analysis(payload, config=None):
    client = get_vision_client(config.get("region"))
    labels_response = client.detect_labels(
        Image={"Bytes": payload["image_bytes"]},
        MaxLabels=int(config.get("max_labels", 10)),
    )
    text_response = client.detect_text(
        Image={"Bytes": payload["image_bytes"]},
    )
    safety_response = client.detect_moderation_labels(
        Image={"Bytes": payload["image_bytes"]},
        MinConfidence=int(config.get("min_confidence", 50)),
    )
    return {
        "labels": normalize_labels(labels_response),
        "text": normalize_text(text_response),
        "safety_score": normalize_safety_score(safety_response),
    }

import re


def check_visual_labels_for_unsafe_text(labels):
    unsafe_keywords = ["violence", "nudity", "gore"]
    for label in labels:
        if any(re.search(keyword, label["name"], re.IGNORECASE) for keyword in unsafe_keywords):
            return True
    return False

import boto3


def archive_image_analysis_artifacts(image_id, artifacts, bucket_name):
    s3 = boto3.client('s3')
    for artifact_type, artifact_content in artifacts.items():
        key = f"{image_id}/{artifact_type}"
        s3.put_object(Bucket=bucket_name, Key=key, Body=artifact_content)
